$ErrorActionPreference = 'Stop'
Set-Location $PSScriptRoot
python -c "import os; os.environ.setdefault('DJANGO_SETTINGS_MODULE', 'flood_detection.settings'); import django; django.setup(); from django.contrib.auth import get_user_model; User = get_user_model(); u = User.objects.filter(username='admin').first(); if u is None: u = User.objects.create_user(username='admin', email='admin@example.com', password='admin123'); else: u.set_password('admin123'); u.email = 'admin@example.com'; u.is_staff = True; u.is_superuser = True; u.role = 'admin'; u.save(); user = User.objects.get(username='admin'); print('USERNAME=' + user.username); print('EMAIL=' + user.email); print('CHECK=' + str(user.check_password('admin123'))); print('IS_SUPER=' + str(user.is_superuser)); print('IS_STAFF=' + str(user.is_staff)); print('ROLE=' + user.role);"
